/* Токены палитры (reference instance, валидирована скриптом) — light + dark. */

.viz-root {
  color-scheme: light;
  --viz-surface: #fcfcfb;
  --viz-text-primary: #0b0b0b;
  --viz-text-secondary: #52514e;
  --viz-text-muted: #898781;
  --viz-gridline: #e1e0d9;
  --viz-baseline: #c3c2b7;
  --viz-border: rgba(11, 11, 11, 0.1);
  --viz-series-1: #2a78d6;
  --viz-series-2: #eb6834;
  --viz-series-3: #1baf7a;

  display: block;
  background: var(--viz-surface);
  border: 1px solid var(--viz-border);
  border-radius: 12px;
  padding: 16px 20px 20px;
  color: var(--viz-text-primary);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root:where(:not([data-theme='light'])) .viz-root {
    color-scheme: dark;
    --viz-surface: #1a1a19;
    --viz-text-primary: #f0efec;
    --viz-text-secondary: #c3c2b7;
    --viz-gridline: #2c2c2a;
    --viz-baseline: #383835;
    --viz-border: rgba(255, 255, 255, 0.1);
    --viz-series-1: #3987e5;
    --viz-series-2: #d95926;
    --viz-series-3: #199e70;
  }
}

:root[data-theme='dark'] .viz-root {
  color-scheme: dark;
  --viz-surface: #1a1a19;
  --viz-text-primary: #f0efec;
  --viz-text-secondary: #c3c2b7;
  --viz-gridline: #2c2c2a;
  --viz-baseline: #383835;
  --viz-border: rgba(255, 255, 255, 0.1);
  --viz-series-1: #3987e5;
  --viz-series-2: #d95926;
  --viz-series-3: #199e70;
}

/* ── Обвязка виджета ── */

.viz-header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}

.viz-titles {
  min-width: 0;
}

.viz-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
}

.viz-subtitle {
  margin: 2px 0 0;
  font-size: 13px;
  color: var(--viz-text-secondary);
}

.viz-controls {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.viz-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  margin: 0 0 8px;
  padding: 0;
  list-style: none;
  font-size: 13px;
  color: var(--viz-text-secondary);
}

.viz-legend li {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.viz-legend-key {
  display: inline-block;
  width: 16px;
  height: 2px;
  border-radius: 1px;
  flex-shrink: 0;
}

.viz-plot-wrap {
  position: relative;
  height: 300px; /* высота включает полосу подписей оси X — без вложенного скролла */
  outline: none;
  transition: opacity 120ms ease;
}

.viz-plot-wrap:focus-visible {
  box-shadow: 0 0 0 2px var(--viz-series-1);
  border-radius: 4px;
}

.viz-plot {
  position: absolute;
  inset: 0;
}

.viz-tooltip {
  position: absolute;
  transform: translate(-50%, calc(-100% - 14px));
  min-width: 168px;
  padding: 8px 10px;
  background: var(--viz-surface);
  border: 1px solid var(--viz-border);
  border-radius: 8px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
  pointer-events: none;
  font-size: 12px;
  z-index: 2;
}

.viz-tooltip-title {
  margin-bottom: 6px;
  font-weight: 600;
  color: var(--viz-text-primary);
}

.viz-tooltip-row {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 2px 0;
}

.viz-tooltip-key {
  display: inline-block;
  width: 12px;
  height: 2px;
  border-radius: 1px;
  flex-shrink: 0;
}

.viz-tooltip-name {
  color: var(--viz-text-secondary);
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.viz-tooltip-value {
  font-weight: 600;
  color: var(--viz-text-primary);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.viz-busy {
  position: absolute;
  top: 8px;
  right: 8px;
}

/* ── Табличный вид ── */

.viz-table-wrap {
  height: 300px;
  overflow: auto;
}

.viz-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.viz-table th,
.viz-table td {
  padding: 6px 12px;
  text-align: right;
  border-bottom: 1px solid var(--viz-gridline);
  font-variant-numeric: tabular-nums; /* колонки чисел выравниваются вертикально */
  white-space: nowrap;
}

.viz-table th:first-child,
.viz-table td:first-child,
.viz-table th[scope='row'] {
  text-align: left;
}

.viz-table thead th {
  position: sticky;
  top: 0;
  background: var(--viz-surface);
  color: var(--viz-text-secondary);
  font-weight: 500;
  z-index: 1;
}

.viz-table thead th .viz-legend-key {
  margin-right: 7px;
}

.viz-table tbody th {
  font-weight: 400;
  color: var(--viz-text-secondary);
}

.viz-note {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--viz-text-muted);
}

